"""Original directional machining microtexture; optical settings are visual estimates."""
import bpy,numpy as np,math,json,hashlib
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];OUT=ROOT/'creative/reviews/front-fork-inner-tube-v1';TEX=HERE/'textures';TEX.mkdir(exist_ok=True)
bpy.ops.wm.open_mainfile(filepath=str(HERE/'front-fork-inner-tube-v1.blend'));o=bpy.data.collections['WEWA_FORK_INNER_TUBE_ISOLATED'].objects[0]
