before=signature();N=512;tile=.008;seed=121017;rng=np.random.default_rng(seed);freq=np.fft.fftfreq(N,d=tile/N);fx,fy=np.meshgrid(freq,freq);field=np.fft.ifft2(np.fft.fft2(rng.normal(size=(N,N)))*np.exp(-2*math.pi**2*((fx*.0008/3)**2+(fy*.00008/3)**2))).real;field=(field-field.mean())/field.std();height=field*.00000012;dx=(np.roll(height,-1,1)-np.roll(height,1,1))/(2*tile/N);dy=(np.roll(height,-1,0)-np.roll(height,1,0))/(2*tile/N);normal=np.stack([-dx,-dy,np.ones_like(dx)],-1);normal/=np.linalg.norm(normal,axis=-1,keepdims=True)
def image(name,pixels):
 old=bpy.data.images.get(name)
 if old:bpy.data.images.remove(old)
 im=bpy.data.images.new(name,width=N,height=N,alpha=False);im.colorspace_settings.name='Non-Color';im.pixels.foreach_set(np.concatenate([pixels,np.ones((N,N,1))],-1).astype(np.float32).ravel());im.filepath_raw=str(TEX/(name+'.png'));im.file_format='PNG';im.save();im.pack();return im
nm=image('tube-original-directional-normal',(normal+1)/2);settings=[(.15,.009,.08),(.235,.016,.40),(.27,.014,.25)];states=[]
for i,m in enumerate(o.data.materials):
 base=m.node_tree.nodes.get('Principled BSDF').inputs['Base Color'].default_value[:];mean,variation,strength=settings[i];rough=np.clip(mean+variation*field,mean-3*variation,mean+3*variation);orm=image('tube-original-ORM-'+str(i),np.stack([np.ones_like(field),rough,np.ones_like(field)],-1));m.node_tree.nodes.clear();p=m.node_tree.nodes.new('ShaderNodeBsdfPrincipled');p.inputs['Base Color'].default_value=base;output=m.node_tree.nodes.new('ShaderNodeOutputMaterial');m.node_tree.links.new(p.outputs['BSDF'],output.inputs['Surface']);t=m.node_tree.nodes.new('ShaderNodeTexImage');t.image=nm;n=m.node_tree.nodes.new('ShaderNodeNormalMap');n.inputs['Strength'].default_value=strength;m.node_tree.links.new(t.outputs['Color'],n.inputs['Color']);m.node_tree.links.new(n.outputs['Normal'],p.inputs['Normal']);t=m.node_tree.nodes.new('ShaderNodeTexImage');t.image=orm;c=m.node_tree.nodes.new('ShaderNodeSeparateColor');m.node_tree.links.new(t.outputs['Color'],c.inputs['Color']);m.node_tree.links.new(c.outputs['Green'],p.inputs['Roughness']);m.node_tree.links.new(c.outputs['Blue'],p.inputs['Metallic']);states.append({'material':m.name,'roughness_range':[float(rough.min()),float(rough.max())],'normal_strength':strength,'metallic':1})
