bpy.ops.object.select_all(action='DESELECT');o.select_set(True);bpy.context.view_layer.objects.active=o;bpy.ops.export_scene.gltf(filepath=str(HERE/'front-fork-inner-tube-inspection.glb'),export_format='GLB',use_selection=True,export_apply=True,export_texcoords=True,export_normals=True,export_tangents=True);bpy.ops.wm.save_as_mainfile(filepath=str(HERE/'front-fork-inner-tube-v1.blend'),compress=True)
s=json.loads((OUT/'source-geometry-check.json').read_text());s.update({'geometry_signature_preserved_by_materials':before,'source_sha256':hashlib.sha256((HERE/'front-fork-inner-tube-v1.blend').read_bytes()).hexdigest(),'export_sha256':hashlib.sha256((HERE/'front-fork-inner-tube-inspection.glb').read_bytes()).hexdigest()});(OUT/'source-geometry-check.json').write_text(json.dumps(s,indent=2)+'\n');(HERE/'build-report.json').write_text(json.dumps(s,indent=2)+'\n');report={'source_sha256':s['source_sha256'],'export_sha256':s['export_sha256'],'original_procedural_pixels':True,'seed':seed,'resolution_px':[N,N],'physical_tile_m':tile,'UV_method':'Cylindrical reference circumference31mm for both walls; XY lips planar','physical_tile_scope':'8mm main OD31mm and XY lips; approximately7.69mm lower and6.45mm inner circumferential repeats, estimated optical scale','height_rms_m_estimated':float(height.std()),'correlation_m_estimated':{'circumferential':.0008,'axial':.00008},'materials':states,'chemical_surface_measured':False,'source_photo_pixels_used':False,'art_accepted':False};(OUT/'material-build-report.json').write_text(json.dumps(report,indent=2)+'\n');print('WEWA_TUBE_MATERIAL',json.dumps(report))
